    let source = b"<svg xmlns:xlink='http://www.w3.org/1999/xlink' width='8' foreign:label='kept'><rect x='1' width='2' foreign:label='kept'/><path x='1'/></svg>";
    let tokens = parsed(source);
    let root = tokens
        .iter()
        .position(|t| t.kind == TokenKind::StartElement)
        .unwrap();
    let rect = tokens
        .iter()
        .position(|t| {
            t.kind == TokenKind::EmptyElement && t.local_name.slice(source) == Some(b"rect")
        })
        .unwrap();
    let path = tokens
        .iter()
        .position(|t| {
            t.kind == TokenKind::EmptyElement && t.local_name.slice(source) == Some(b"path")
        })
        .unwrap();
    let rect_kind = tokens[rect].local_name;
    let path_kind = tokens[path].local_name;
    assert!(attributes_supported(
        source,
        &tokens,
        root,
        true,
        tokens[root].local_name
    ));
    assert!(attributes_supported(
        source, &tokens, rect, false, rect_kind
    ));
    assert!(!attributes_supported(
        source, &tokens, path, false, path_kind
    ));

    let bad = b"<svg><rect svg:width='2'/></svg>";
    let bad_tokens = parsed(bad);
    let rect = bad_tokens
        .iter()
        .position(|t| t.kind == TokenKind::EmptyElement)
        .unwrap();
    assert!(!attributes_supported(
        bad,
        &bad_tokens,
        rect,
        false,
        bad_tokens[rect].local_name
    ));
}

